 style = MaterialTheme.typography.titleMedium,
 fontWeight = FontWeight.Bold,
 color = if (hasPermissions) MaterialTheme.colorScheme.primary else Color(0xFFD84315)
 )
 Text(
 text = if (hasPermissions) "SMS access is enabled" else "Enable SMS access to continue",
 style = MaterialTheme.typography.bodySmall,
 color = MaterialTheme.colorScheme.onSurfaceVariant
 )
 }

 if (!hasPermissions) {
 Button(
 onClick = {
 permissionsState.launchMultiplePermissionRequest()
 },
 colors = ButtonDefaults.buttonColors(
 containerColor = Color(0xFFFF5722),
 contentColor = Color.White
 ),
 shape = RoundedCornerShape(12.dp)
 ) {
 Text("Grant", fontWeight = FontWeight.SemiBold)
 }
 }
 }
 }
 }

 Spacer(modifier = Modifier.height(28.dp))

 // Enhanced Bank Numbers Section
 Card(
 modifier = Modifier.fillMaxWidth(),
 shape = RoundedCornerShape(20.dp),
 colors = CardDefaults.cardColors(
 containerColor = MaterialTheme.colorScheme.surface
 ),
 elevation = CardDefaults.cardElevation(defaultElevation = 8.dp)
 ) {
 Column(
 modifier = Modifier.padding(24.dp)
 ) {
 // Header with gradient background
 Row(
 modifier = Modifier
 .fillMaxWidth()
 .clip(RoundedCornerShape(12.dp))
 .background(
 brush = Brush.horizontalGradient(
 colors = listOf(
 MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.3f),
 MaterialTheme.colorScheme.secondaryContainer.copy(alpha = 0.2f)
 )
 )
 )
 .padding(16.dp),
 horizontalArrangement = Arrangement.SpaceBetween,
 verticalAlignment = Alignment.CenterVertically
 ) {
 Column {
 Text(
 text = "Bank Numbers",
 style = MaterialTheme.typography.titleLarge,
 fontWeight = FontWeight.Bold,
 color = MaterialTheme.colorScheme.primary
 )
 if (state.savedBankNumbers.isNotEmpty()) {
 Text(
 text = "✓ ${state.savedBankNumbers.size} numbers saved",
 style = MaterialTheme.typography.bodySmall,
 color = MaterialTheme.colorScheme.primary,
 fontWeight = FontWeight.Medium
 )
 } else {
 Text(
 text = "No numbers saved yet",
 style = MaterialTheme.typography.bodySmall,
 color = MaterialTheme.colorScheme.onSurfaceVariant
 )
 }
 }
 Surface(
 shape = RoundedCornerShape(20.dp),
 color = MaterialTheme.colorScheme.primary.copy(alpha = 0.1f)
 ) {
 Text(
 text = "${bankNumbers.size}/4",
 style = MaterialTheme.typography.labelLarge,
 fontWeight = FontWeight.Bold,
 color = MaterialTheme.colorScheme.primary,
 modifier = Modifier.padding(horizontal = 12.dp, vertical = 6.dp)
 )
 }
 }

 Spacer(modifier = Modifier.height(20.dp))

 // Enhanced Bank Number Text Fields
 LazyColumn(
 verticalArrangement = Arrangement.spacedBy(16.dp),
 modifier = Modifier.padding(bottom = 10.dp).heightIn(max = 320.dp)
 ) {
 itemsIndexed(bankNumbers) { index, number ->
 EnhancedBankNumberField(
 value = number,
 onValueChange = { newValue ->
 bankNumbers = bankNumbers.toMutableList().apply {
 this[index] = newValue
 }
 },
 onDelete = if (bankNumbers.size > 1 && index > 0) {
 {
 bankNumbers = bankNumbers.toMutableList().apply {
 removeAt(index)
 }
 }
 } else null,
 index = index
 )
 Spacer(modifier = Modifier.height(10.dp))

 }

 }

 Spacer(modifier = Modifier.height(20.dp))

 // Enhanced Action Buttons
 Row(
 modifier = Modifier.fillMaxWidth(),
 horizontalArrangement = Arrangement.spacedBy(12.dp)
 ) {
 Button(
 onClick = {
 if (bankNumbers.size < 4) {
 bankNumbers = bankNumbers + ""
 }
 },
 enabled = bankNumbers.size < 4,
 modifier = Modifier.weight(1f),
 shape = RoundedCornerShape(14.dp),
 colors = ButtonDefaults.outlinedButtonColors(
 contentColor = MaterialTheme.colorScheme.primary
 ),
 border = androidx.compose.foundation.BorderStroke(
 2.dp,
 MaterialTheme.colorScheme.primary.copy(alpha = 0.5f)
 )
 ) {
 Icon(
 Icons.Default.Add,
 contentDescription = null,
 modifier = Modifier.size(18.dp)
 )
 Spacer(modifier = Modifier.width(6.dp))
 Text("Add ", fontWeight = FontWeight.SemiBold)

 }

 }
 }
 }

 Spacer(modifier = Modifier.height(24.dp))

 // Enhanced Latest Message Section
 if (state.latestMessage.isNotBlank()) {
 Card(
 modifier = Modifier.fillMaxWidth(),
 shape = RoundedCornerShape(18.dp),
 colors = CardDefaults.cardColors(
 containerColor = Color(0xFF673AB7).copy(alpha = 0.1f)
 ),
 border = androidx.compose.foundation.BorderStroke(
 1.dp,
 Color(0xFF673AB7).copy(alpha = 0.2f)
 ),
 elevation = CardDefaults.cardElevation(defaultElevation = 6.dp)
 ) {
 Column(
 modifier = Modifier.padding(20.dp)
 ) {
 Row(
 verticalAlignment = Alignment.CenterVertically,
 horizontalArrangement = Arrangement.spacedBy(8.dp)
 ) {
 Surface(
 shape = RoundedCornerShape(8.dp),
 color = Color(0xFF673AB7).copy(alpha = 0.2f)
 ) {
 Icon(
 Icons.Default.Email,
 contentDescription = null,
 tint = Color(0xFF673AB7),
 modifier = Modifier
 .size(20.dp)
 .padding(2.dp)
 )
 }
 Text(
 text = "Latest Message",
 style = MaterialTheme.typography.titleMedium,
 fontWeight = FontWeight.Bold,
 color = Color(0xFF4527A0)
 )
 }
 Spacer(modifier = Modifier.height(12.dp))
 Text(
 text = state.latestMessage,
 style = MaterialTheme.typography.bodyMedium,
 color = MaterialTheme.colorScheme.onSurface,
 lineHeight = MaterialTheme.typography.bodyMedium.lineHeight
 )
 }
 }
 Spacer(modifier = Modifier.height(20.dp))
 }

 // Enhanced Main Action Button
 Button(
 onClick = {
 val validNumbers = bankNumbers.filter { it.isNotBlank() }
 if (validNumbers.isNotEmpty()) {
 viewModel.dispatch(
 SmsIntent.SetBankNumbers(
 numbers = validNumbers
 )
 )
 }
 },
 modifier = Modifier
 .fillMaxWidth()
 .height(64.dp),
 shape = RoundedCornerShape(20.dp),
 colors = ButtonDefaults.buttonColors(
 containerColor = MaterialTheme.colorScheme.primary,
 disabledContainerColor = MaterialTheme.colorScheme.primary.copy(alpha = 0.4f)
 ),
 enabled = bankNumbers.any { it.isNotBlank() } &&
 bankNumbers.filter { it.isNotBlank() } != state.savedBankNumbers,
 elevation = ButtonDefaults.buttonElevation(defaultElevation = 8.dp)
 ) {
 Text(
 if (state.savedBankNumbers.isEmpty()) "Save Numbers" else "Update Numbers",
 style = MaterialTheme.typography.titleMedium,
 fontWeight = FontWeight.Bold,
 color = Color.White
 )
 }
 }
 },
 )


}

@SuppressLint("UnusedMaterial3ScaffoldPaddingParameter")
@Composable
private fun EnhancedBankNumberField(
 value: String,
 onValueChange: (String) -> Unit,
 onDelete: (() -> Unit)?,
 index: Int
) {
 Card(
 modifier = Modifier.fillMaxWidth(),
 shape = RoundedCornerShape(16.dp),
 elevation = CardDefaults.cardElevation(defaultElevation = 2.dp)
 ) {
 Row(
 modifier = Modifier
 .fillMaxWidth()
 .background(Color.White)
 .padding(16.dp),
 verticalAlignment = Alignment.CenterVertically,
 horizontalArrangement = Arrangement.spacedBy(12.dp)
 ) {
 // Number indicator
 Surface(
 shape = RoundedCornerShape(8.dp),
 color = MaterialTheme.colorScheme.primary.copy(alpha = 0.1f)
 ) {
 Text(
 text = "${index + 1}",
 style = MaterialTheme.typography.labelMedium,
 fontWeight = FontWeight.Bold,
 color = MaterialTheme.colorScheme.primary,
 modifier = Modifier.padding(8.dp)
 )
 }

 OutlinedTextField(
 value = value,
 onValueChange = onValueChange,
 label = {
 Text(
 "Bank Number",
 color = MaterialTheme.colorScheme.primary
 )
 },
 placeholder = {
 Text(
 "Enter bank number",
 color = MaterialTheme.colorScheme.onSurfaceVariant
 )
 },
 modifier = Modifier.weight(1f),
 shape = RoundedCornerShape(14.dp),
 colors = OutlinedTextFieldDefaults.colors(
 focusedBorderColor = MaterialTheme.colorScheme.primary,
 focusedLabelColor = MaterialTheme.colorScheme.primary,
 unfocusedBorderColor = MaterialTheme.colorScheme.outline.copy(alpha = 0.5f),
 focusedContainerColor = Color.Transparent,
 unfocusedContainerColor = Color.Transparent
 ),
 )

 if (onDelete != null) {
 IconButton(
 onClick = onDelete,
 colors = IconButtonDefaults.iconButtonColors(
 containerColor = Color(0xFFFF5722).copy(alpha = 0.1f),
 contentColor = Color(0xFFD84315)
 )
 ) {
 Icon(
 Icons.Default.Delete,
 contentDescription = "Delete",
 modifier = Modifier.size(20.dp)
 )
 }
 }
 }
 }
}

